package io.github.offlineglass.hook.adapters.douyin

/** Original extracted TikTok PNG bytes, embedded to avoid cross-package asset access.
 * Generated from app/src/main/assets/tiktok; regenerate when the artwork changes. */
internal object DouyinIconArtwork {
    fun bytes(name: String): ByteArray? = when (name) {
        "home" -> android.util.Base64.decode("", android.util.Base64.DEFAULT)
        "friends" -> android.util.Base64.decode("", android.util.Base64.DEFAULT)
        "publish" -> android.util.Base64.decode("", android.util.Base64.DEFAULT)
        "inbox" -> android.util.Base64.decode("", android.util.Base64.DEFAULT)
        "profile" -> android.util.Base64.decode("", android.util.Base64.DEFAULT)
        "home_fill" -> android.util.Base64.decode("", android.util.Base64.DEFAULT)
        "friends_fill" -> android.util.Base64.decode("", android.util.Base64.DEFAULT)
        "inbox_fill" -> android.util.Base64.decode("", android.util.Base64.DEFAULT)
        "profile_fill" -> android.util.Base64.decode("", android.util.Base64.DEFAULT)
        else -> null
    }
}
